  if (LM_NON_ENGLISH_CHARS.test(t) || LM_SPANISH_WORDS.test(t)) return false;
  var vistas = {}, n = 0, m;
  LM_SPANISH_STOPWORDS.lastIndex = 0;
  while ((m = LM_SPANISH_STOPWORDS.exec(t)) !== null) {
    var w = m[0].toLowerCase();
